import pandas as pd
from pandas import Timedelta
import numpy as np

# Example 1: Timedelta(nanoseconds=999).total_seconds()
try:
    result = Timedelta(nanoseconds=999).total_seconds()
    probe("Timedelta(nanoseconds=999).total_seconds()", result)
except Exception as e:
    probe("Timedelta(nanoseconds=999).total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 1
try:
    expected = 9.99e-7
    probe("expected::Timedelta(nanoseconds=999).total_seconds()", expected)
except Exception as e:
    probe("expected::Timedelta(nanoseconds=999).total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: Timedelta('1us 500ns').total_seconds()
try:
    result = Timedelta('1us 500ns').total_seconds()
    probe("Timedelta('1us 500ns').total_seconds()", result)
except Exception as e:
    probe("Timedelta('1us 500ns').total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 2
try:
    expected = 1.5e-6
    probe("expected::Timedelta('1us 500ns').total_seconds()", expected)
except Exception as e:
    probe("expected::Timedelta('1us 500ns').total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 3: Timedelta(nanoseconds=-1).total_seconds()
try:
    result = Timedelta(nanoseconds=-1).total_seconds()
    probe("Timedelta(nanoseconds=-1).total_seconds()", result)
except Exception as e:
    probe("Timedelta(nanoseconds=-1).total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 3
try:
    expected = -1e-9
    probe("expected::Timedelta(nanoseconds=-1).total_seconds()", expected)
except Exception as e:
    probe("expected::Timedelta(nanoseconds=-1).total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 4: Timedelta(1_552_211_999_999_999_999).total_seconds() (1 ns below 1552212000 s)
try:
    result = Timedelta(1_552_211_999_999_999_999).total_seconds()
    probe("Timedelta(1_552_211_999_999_999_999).total_seconds()", result)
except Exception as e:
    probe("Timedelta(1_552_211_999_999_999_999).total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected: should be strictly less than 1552212000
try:
    # We record that it should be strictly less than 1552212000
    expected_threshold = 1552212000
    probe("expected::Timedelta(1_552_211_999_999_999_999).total_seconds() < 1552212000", expected_threshold)
except Exception as e:
    probe("expected::Timedelta(1_552_211_999_999_999_999).total_seconds() < 1552212000", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 5: Timedelta(1_552_212_000_000_000_001).total_seconds() (1 ns above 1552212000 s)
try:
    result = Timedelta(1_552_212_000_000_000_001).total_seconds()
    probe("Timedelta(1_552_212_000_000_000_001).total_seconds()", result)
except Exception as e:
    probe("Timedelta(1_552_212_000_000_000_001).total_seconds()", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected: should be strictly greater than 1552212000
try:
    expected_threshold = 1552212000
    probe("expected::Timedelta(1_552_212_000_000_000_001).total_seconds() > 1552212000", expected_threshold)
except Exception as e:
    probe("expected::Timedelta(1_552_212_000_000_000_001).total_seconds() > 1552212000", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 6: pd.to_timedelta([5e-7], 's')[0].total_seconds()
